javascriptVariables.Microsoft UET - product IDs:
function() {
  var items = {{DLV - commerce.items}};
  var ids = [];
  var index;

  if (!items || !items.length) return;

  for (index = 0; index < items.length; index += 1) {
    var candidate = items[index] && (items[index].variant_id || items[index].item_id);
    var match;

    if (typeof candidate !== 'string') continue;

    match = /^gid:\/\/shopify\/ProductVariant\/(\d+)$/.exec(candidate);
    if (match) {
      ids.push(match[1]);
    } else if (/^[A-Za-z0-9-]{1,50}$/.test(candidate)) {
      ids.push(candidate);
    }
  }

  return ids.length ? ids : undefined;
}
